/*
  Concepts: Cardiac Devices (same shape as data/diseases-endocrine.js).

  Each entry is a mechanism, not a disease: idea → cause/effect chain →
  bedside relevance → common traps, with a prediction-style question bank.
  Source: source-material/cardio-part-1/text/cardiac-devices.md (Gulczinski).
  Recall facts (indication lists, follow-up schedule, distances) live in
  data/cardiac-devices.js; here they appear only where they explain a "why".
  Anything the slides only imply is labeled "Clarification (standard
  physiology)" in the html.

  Question ids are "<concept id>|<index>" and progress is saved against them:
  only APPEND questions to a concept; never insert, delete, or reorder.
  `correct` is zero-based; the engine shuffles answer order every time.
*/
(function () {
  "use strict";

  var H = window.DiseaseContent;
  var Tbl = H.Tbl, HY = H.HY, Mn = H.Mn, S = H.S, Q = H.Q, D = H.D, L = H.L;

  function chain(steps) {
    return '<ol class="concept-chain">' + steps.map(function (step) { return "<li>" + step + "</li>"; }).join("") + "</ol>";
  }
  function clar(text) {
    return "<p><strong>Clarification (standard physiology):</strong> " + text + "</p>";
  }
  function traps(items) {
    return "<ul>" + items.map(function (item) { return "<li>" + item + "</li>"; }).join("") + "</ul>";
  }

  window.CARDIO_CONCEPTS_DEVICES = L("cardiac-devices", "Cardiac Devices", [

    // ------------------------------------------------------------------
    D("dev-reversible-first", "Fix the reversible cause before pacing", "A permanent pacemaker is for a conduction system that is permanently broken, so a slow rhythm caused by a drug, an electrolyte, ischemia, infection, or trauma is treated at its cause and only bridged with temporary pacing if needed.", [
      S("idea", "The idea", "<p>A <strong>permanent pacemaker (PPM)</strong> is a lifelong implant for a conduction system that is <strong>itself diseased</strong> — usually the AV node or His-Purkinje system, sometimes the sinus node.</p><p>But plenty of slow rhythms come from something <em>outside</em> the conduction system that is temporarily pressing the brakes: an AV-nodal-blocking drug, a severe electrolyte or metabolic problem, ischemia/MI, an infection like Lyme disease or endocarditis, or chest trauma. Take the brake off and the heart's own wiring works again.</p><p>So the question is never just “is the heart slow?” but “<strong>will it still be slow once I fix what is causing it?</strong>” Only a “yes” earns a permanent device. While you wait to find out, the patient is <strong>monitored</strong> — crash cart nearby or pacer pads on — and, if unstable, bridged with <strong>temporary</strong> pacing.</p>"),
      S("chain", "Cause → effect", chain([
        "A reversible insult (AV-nodal-blocking drug, electrolyte/toxic-metabolic disturbance, ischemia/MI, Lyme or IE, chest trauma) slows or blocks conduction.",
        "The conduction tissue is suppressed, not permanently destroyed.",
        "Hold the drug, correct the metabolic problem, or treat the disease → the brake is removed.",
        "Conduction recovers → no lifelong device, no lead or pocket risks.",
        "If the bradycardia persists after every reversible cause is corrected → the conduction system itself is diseased → now a PPM is indicated (if symptomatic and meets criteria)."
      ]) + Tbl(["Situation", "What happens to the rhythm", "Device decision"], [
        ["Cause removed, rhythm recovers", "Heart rate returns to normal", "<strong>No PPM</strong>"],
        ["Cause removed, rhythm stays slow / blocked", "Intrinsic conduction disease", "<strong>PPM</strong> evaluation by EP"],
        ["Unstable while the cause is being treated", "Life-threatening lack of intrinsic pacing", "<strong>Temporary</strong> pacing (transcutaneous → transvenous) as a bridge"]
      ]) + HY("Correct every reversible cause first; a permanent device is for a permanent problem.")),
      S("bedside", "Why it matters clinically", "<p>The slides list these as times a bradyarrhythmia does <strong>not</strong> warrant a PPM:</p><ul><li>“Under the influence” of AV-nodal-blocking medications</li><li>Severe electrolyte disturbances or toxic/metabolic abnormalities</li><li>Myocardial ischemia or infarction</li><li>Infectious causes (Lyme disease, IE)</li><li>After chest trauma</li></ul><p>Temporary pacing fills the gap: <strong>transcutaneous</strong> pacing is painful and needs sedation, so it is used for a minimal time until a <strong>transvenous</strong> wire is placed; transvenous wires are a bridge (strict bedrest) to a permanent device when one is needed. Lyme or Chagas disease causing interval changes is itself listed as an indication for <em>temporary</em> pacing.</p><p>Patients who do need a PPM present with exertional dyspnea, loss of exercise tolerance, syncope or near syncope — the brain and muscles are under-perfused because the rate is too slow to keep up cardiac output.</p>" + clar("cardiac output = heart rate × stroke volume, so a slow rate that the heart cannot offset produces the exertional and syncopal symptoms the slides list.")),
      S("traps", "Common traps", traps([
        "<strong>“Complete heart block = PPM, always.”</strong> Heart block from an AV-nodal blocker, a severe electrolyte disturbance, MI, or Lyme disease may resolve once the cause is treated; the device decision comes after.",
        "<strong>“Temporary pacing means a permanent device is coming.”</strong> Temporary pacing is a bridge for instability; the patient may recover and never need a PPM.",
        "<strong>“Reversible means safe to ignore.”</strong> While the cause is treated the patient is monitored closely, with a crash cart nearby or pacer pads applied.",
        "<strong>“Transcutaneous pacing is a long-term option.”</strong> It is painful and needs sedation, so it is used only until a transvenous wire can be placed."
      ]))
    ], [
      Q("chain", "A patient on an AV-nodal-blocking drug develops symptomatic bradycardia that resolves when the drug is held. What does this predict about the need for a permanent pacemaker?", ["None is needed — the conduction system recovered once the brake was removed", "A PPM is needed because the bradycardia was symptomatic", "An ICD is needed instead of a PPM", "A biventricular device is needed"], 0, "The drug suppressed conduction rather than destroying it; removing it restored the rhythm, so there is no permanent problem for a permanent device to fix."),
      Q("chain", "After every reversible cause is corrected, a patient's complete heart block persists and he still has near-syncope. What does this tell you?", ["The conduction system itself is diseased, so a permanent pacemaker is now appropriate", "The block must still be drug-induced", "He should stay on transcutaneous pacing indefinitely", "An ICD is the correct device for heart block"], 0, "Persistence after the reversible causes are removed means the AV node or His-Purkinje system is intrinsically diseased — the setting for a PPM."),
      Q("idea", "Why are reversible causes corrected before a permanent pacemaker is placed?", ["A PPM is lifelong hardware for a permanently diseased conduction system, and many slow rhythms recover when the cause is treated", "Pacemakers do not work in patients with electrolyte problems", "Reversible causes make the implant procedure longer", "Insurance will not pay for a PPM until labs are normal"], 0, "The device is permanent and carries lead and infection risks; implanting it for a rhythm that would have recovered exposes the patient to those risks for no benefit."),
      Q("bedside", "A patient with an inferior MI develops high-grade AV block and hypotension. What is the reasoning for the next step?", ["Treat the ischemia and bridge with temporary pacing, because MI-related block may recover", "Place a permanent pacemaker immediately because the block is symptomatic", "Place an ICD because the patient had an MI", "Observe without monitoring because MI block is always benign"], 0, "Ischemia/MI is on the list of reversible causes; the unstable patient is bridged with temporary pacing while the underlying disease is treated."),
      Q("bedside", "A patient with Lyme disease has new heart block. Which device approach fits the lecture's reasoning?", ["Treat the infection; temporary pacing if hemodynamically unstable", "Permanent dual-chamber pacemaker before antibiotics", "Subcutaneous ICD", "No monitoring is needed because Lyme block is not dangerous"], 0, "Infectious causes such as Lyme are reversible, and Lyme or Chagas causing interval changes is listed as an indication for temporary — not permanent — pacing."),
      Q("traps", "Why is transcutaneous pacing used only briefly?", ["It is painful and usually requires sedation, so it bridges only until a transvenous wire is placed", "It cannot capture the ventricle", "It requires a surgical pocket", "It works only for tachyarrhythmias"], 0, "Transcutaneous pacing delivers current through the chest wall, which is painful; a transvenous wire replaces it as soon as possible."),
      Q("chain", "Why does symptomatic bradycardia cause exertional dyspnea and syncope?", ["Too slow a rate lowers cardiac output, so the brain and muscles are under-perfused, especially with exertion", "Bradycardia raises cardiac output beyond what tissues need", "Slow heart rates cause bronchospasm", "Bradycardia causes syncope only by triggering seizures"], 0, "Cardiac output depends on heart rate; when the rate is too slow and cannot rise with activity, output falls and the patient gets exertional dyspnea, loss of exercise tolerance, and near-syncope or syncope.")
    ]),

    // ------------------------------------------------------------------
    D("dev-sense-pace-inhibit", "Sensing, pacing, and inhibition", "A demand pacemaker listens before it fires: if it senses the heart's own beat it holds back, and only if nothing comes does it pace — while an asynchronous pacer fires on a fixed schedule no matter what the heart is doing.", [
      S("idea", "The idea", "<p>A pacemaker does two separate jobs through its leads: it can <strong>sense</strong> (listen for the heart's own electrical beat) and it can <strong>pace</strong> (deliver an impulse that depolarizes the chamber). The pulse generator is the battery and the “brain” that decides what to do with what it hears.</p><p>Think of a substitute teacher who only takes over if the regular teacher doesn't show up. In <strong>demand (synchronous)</strong> mode the device waits: if the heart produces its own beat on time, the device is <strong>inhibited</strong> and stays quiet; if the expected beat never comes, it paces.</p><p>In <strong>fixed-rate (asynchronous)</strong> mode the device ignores the heart and fires at a set rate regardless. That guarantees a rhythm, but a paced impulse can land on the heart's own <strong>T wave</strong> — its vulnerable period — and carries a small risk of triggering a lethal arrhythmia.</p>"),
      S("chain", "Cause → effect", chain([
        "The sensing circuit listens for an intrinsic depolarization in the chamber it monitors.",
        "Intrinsic beat sensed in time → the device is inhibited → no pacing spike (the heart's own beat is used).",
        "No intrinsic beat by the end of the programmed interval → the generator delivers a pacing impulse through the lead → the chamber depolarizes.",
        "Asynchronous mode skips the listening step → impulses at a set rate independent of the heart.",
        "Because asynchronous impulses ignore the heart's own beats, one can fall on the T wave's vulnerable period → small risk of a lethal arrhythmia."
      ]) + Tbl(["Mode", "Listens?", "If the heart beats on its own", "If the heart is silent", "Main risk"], [
        ["Demand (synchronous)", "Yes", "<strong>Inhibited</strong> — no spike", "Paces", "Can be fooled by false signals (oversensing)"],
        ["Fixed-rate (asynchronous)", "No", "Paces anyway (competes with the heart)", "Paces", "Impulse on the T wave → lethal arrhythmia"]
      ]) + HY("Demand pacing = sense first, pace only if nothing is sensed; asynchronous = pace on schedule regardless.")),
      S("bedside", "Why it matters clinically", "<p>This one idea explains several later slides:</p><ul><li><strong>Oversensing during surgery:</strong> a demand pacer “hears” electrocautery noise as heartbeats and is inhibited — so a pacemaker-dependent patient can become profoundly bradycardic or asystolic.</li><li><strong>The magnet:</strong> a magnet over most pacemakers switches them to <strong>asynchronous</strong> pacing at a fixed rate, which removes the listening step so noise can no longer inhibit it.</li><li><strong>Pacing code third letter:</strong> “I” (inhibited) describes exactly the demand behavior above; “O” usually means continuous pacing.</li><li><strong>Leads that only sense:</strong> some leads are sensing leads only; listening and pacing are separate functions.</li></ul>"),
      S("traps", "Common traps", traps([
        "<strong>“A working pacemaker fires on every beat.”</strong> A demand pacer that sees no spikes may simply be inhibited by a normal intrinsic rhythm.",
        "<strong>“Asynchronous pacing is the safer mode.”</strong> It cannot be inhibited by noise, but it competes with the heart and carries the small T-wave vulnerable-period risk.",
        "<strong>“Sensing and pacing are the same thing.”</strong> Sensing is listening; pacing is stimulating. A lead can sense without pacing.",
        "<strong>“Inhibited means broken.”</strong> Inhibition is the intended response to the patient's own beat."
      ]))
    ], [
      Q("chain", "A demand pacemaker senses the patient's own ventricular beat on time. What does the device do?", ["It is inhibited and does not pace that beat", "It paces immediately on top of the native beat", "It shocks the patient", "It switches permanently to asynchronous mode"], 0, "In demand (synchronous) mode, a sensed intrinsic beat inhibits the device; it paces only when no beat is sensed."),
      Q("chain", "The heart fails to produce a beat by the end of the programmed interval in a demand pacer. What happens?", ["The generator delivers a pacing impulse to depolarize the chamber", "The device stays silent because it is inhibited", "The device waits for a magnet to be applied", "The device delivers an 80-joule shock"], 0, "No sensed intrinsic depolarization → the sensing circuit lets the generator fire a pacing impulse."),
      Q("chain", "Why does asynchronous (fixed-rate) pacing carry a small risk of a lethal arrhythmia?", ["It ignores the heart's own beats, so an impulse can land on the T wave's vulnerable period", "It paces too slowly to support cardiac output", "It drains the battery and stops pacing", "It only paces the atria"], 0, "Fixed-rate impulses are independent of intrinsic activity, so one can coincide with the vulnerable period of the T wave."),
      Q("idea", "A patient's ECG shows no pacing spikes, and his own rhythm is a normal rate. What is the most likely explanation in a demand pacer?", ["The device is appropriately inhibited by his intrinsic rhythm", "The pacemaker battery is dead", "The lead must be fractured", "The device is in asynchronous mode"], 0, "A demand pacer stays quiet when it senses adequate native beats; absence of spikes with a good native rate is expected behavior."),
      Q("bedside", "Electrical noise is mistaken by a demand pacer for heartbeats. Predict the effect in a pacemaker-dependent patient.", ["The pacer is inhibited → profound bradycardia or asystole", "The pacer fires faster → tachycardia", "The pacer switches to biventricular pacing", "No effect, because pacers cannot sense noise"], 0, "False signals look like intrinsic beats, so the device withholds pacing; a dependent patient has no underlying rhythm to fall back on."),
      Q("traps", "Which statement about sensing vs pacing is correct?", ["Sensing is listening for intrinsic depolarization; pacing is delivering an impulse — a lead can sense without pacing", "Sensing and pacing are the same function", "Only the pulse generator senses; leads only pace", "Pacing always happens before sensing on every beat"], 0, "The slides note leads may be sensing leads only; sensing feeds the generator's decision whether to pace."),
      Q("bedside", "Why does switching a pacemaker to asynchronous mode protect a dependent patient from electrocautery noise?", ["An asynchronous pacer does not listen, so noise cannot inhibit it", "Asynchronous mode filters out all noise but still senses normally", "Asynchronous mode turns the pacer off", "Asynchronous mode increases the shocking energy"], 0, "Removing the sensing step means nothing the device hears can stop it from pacing — the trade-off is the small T-wave risk.")
    ]),

    // ------------------------------------------------------------------
    D("dev-pacer-code", "Reading the pacemaker code to predict behavior", "The pacing code is a sentence about behavior — letter 1 is where it paces, letter 2 is where it listens, letter 3 is what it does with what it hears — so you can predict the device's next move from the letters alone.", [
      S("idea", "The idea", "<p>Rather than memorizing modes, read the code like a sentence:</p><ol><li><strong>1st letter — paces</strong> which chamber? (A, V, D)</li><li><strong>2nd letter — senses</strong> which chamber? (A, V, D, O = none)</li><li><strong>3rd letter — responds</strong> how? (I = inhibited by a sensed native beat; T = triggered by the native atrial beat; D = triggered after a sensed atrial event but inhibited after a sensed ventricular event; O = none, usually pacing continuously)</li><li>4th — <strong>R</strong> = rate response for chronotropic incompetence (O = none)</li><li>5th — multisite pacing (CRT)</li></ol><p>Usually only the first three letters are documented. Once you read them, you can answer any “what will it do next?” question: find where it listens, decide whether a native beat was heard there, and apply the response letter.</p>"),
      S("chain", "Cause → effect", chain([
        "Read letter 2: is there a sensing chamber? If “O”, the device hears nothing and simply paces at its rate.",
        "If it senses: did a native beat occur in the sensed chamber in time?",
        "Apply letter 3: I → a sensed beat inhibits pacing; no beat → it paces the chamber in letter 1.",
        "T → a sensed native atrial beat triggers an added depolarization from the device.",
        "D → a sensed atrial event triggers ventricular pacing, but a sensed ventricular event inhibits it.",
        "Letter 4 “R” → the device raises its pacing rate with activity in a patient whose own rate cannot rise (chronotropic incompetence)."
      ]) + Tbl(["Code", "Paces", "Senses", "Native beat sensed →", "No native beat →"], [
        ["VVI", "Ventricle", "Ventricle", "Inhibited", "Paces the ventricle"],
        ["AAI", "Atrium", "Atrium", "Inhibited", "Paces the atrium"],
        ["VOO", "Ventricle", "None", "(Not sensed — paces anyway)", "Paces the ventricle"],
        ["DDD", "Both", "Both", "Atrial sense triggers; ventricular sense inhibits", "Paces atrium and/or ventricle"],
        ["VVIR", "Ventricle", "Ventricle", "Inhibited", "Paces, with rate rising with activity"]
      ]) + Mn("Pace · Sense · Respond", "1st = where it paces, 2nd = where it listens, 3rd = what it does about what it hears.") + HY("Letter 2 “O” = no sensing = asynchronous/continuous pacing; letter 3 “I” = demand pacing.")),
      S("bedside", "Why it matters clinically", "<p>The objective asks you to interpret the letters in a clinical scenario. The slides' own example is an <strong>ADI</strong> pacer: it paces the right atrium, senses both chambers, and the atrial impulse is <strong>inhibited</strong> if the patient's own depolarization is sensed. The slide then asks: <em>if the atria fail to depolarize on their own, what happens?</em> — no inhibiting beat is sensed, so the device <strong>paces the atrium</strong>.</p><p>The code also explains the magnet and the device types: single-chamber devices have one RV lead (a “V” device), dual-chamber devices have RA and RV leads (“D” possible), and biventricular CRT devices add an LV lead (the 5th-letter multisite pacing).</p>" + clar("the example codes in the table (VVI, AAI, VOO, DDD, VVIR) are built by applying the slide's letter definitions; the slide's only worked example is ADI.")),
      S("traps", "Common traps", traps([
        "<strong>Mixing up letters 1 and 2.</strong> The first letter is where it <em>paces</em>; the second is where it <em>senses</em>.",
        "<strong>“O in the 3rd position means the device is off.”</strong> It means no response to sensing — usually it is pacing continuously.",
        "<strong>“R means it paces the right side.”</strong> R in the 4th position is rate response for chronotropic incompetence, not a chamber.",
        "<strong>“A dual-chamber device is biventricular.”</strong> Dual = RA + RV; biventricular (CRT) = RA + RV + LV."
      ]))
    ], [
      Q("chain", "A VVI pacemaker senses the patient's own ventricular beat. What happens?", ["Ventricular pacing is inhibited for that beat", "The ventricle is paced on top of the native beat", "The atrium is paced", "The device shocks the ventricle"], 0, "VVI: paces V, senses V, I = inhibited by a sensed native beat."),
      Q("chain", "In the slide's ADI example, the atria fail to depolarize on their own. What will the device do?", ["Pace the right atrium, because no inhibiting native beat was sensed", "Stay silent because it is inhibited", "Pace the left ventricle", "Deliver a shock"], 0, "ADI paces the atrium and is inhibited only by a sensed native depolarization; with none sensed, it paces the atrium."),
      Q("idea", "What does the second letter of a pacemaker code tell you?", ["The chamber being sensed", "The chamber being paced", "The response to a sensed beat", "Whether rate response is present"], 0, "1st = paced, 2nd = sensed, 3rd = response, 4th = rate modulation, 5th = multisite pacing."),
      Q("chain", "A device's code has “O” as its second letter. Predict its behavior.", ["It senses nothing, so it paces at its set rate regardless of the heart's own beats", "It is turned off", "It senses both chambers", "It paces only when a native beat is sensed"], 0, "No sensing chamber means nothing can inhibit or trigger it — it paces continuously, i.e., asynchronously."),
      Q("chain", "A patient's own heart rate cannot rise with exercise. Which part of the code addresses this?", ["Fourth letter R — rate-responsive pacing", "Third letter T — triggered pacing", "Second letter D — dual sensing", "Fifth letter V — ventricular multisite pacing"], 0, "The fourth letter is rate modulation; R lets the device increase its rate for chronotropic incompetence."),
      Q("chain", "A DDD device senses an atrial event. What is the device's response, per the code definition?", ["It is triggered to follow with ventricular pacing unless a ventricular event is sensed, which inhibits it", "It is inhibited in both chambers permanently", "It shocks the ventricle", "It ignores the atrial event"], 0, "Third letter D = triggered after a sensed atrial event but inhibited after a sensed ventricular event."),
      Q("traps", "Which statement about a pacemaker code is correct?", ["“O” in the third position usually means the device paces continuously", "“R” in the fourth position means right ventricular pacing", "The first letter is the chamber sensed", "A dual-chamber device always includes a left ventricular lead"], 0, "O = no response mode, typically continuous pacing; R is rate response; the first letter is the paced chamber; dual chamber = RA + RV."),
      Q("bedside", "A biventricular device is placed in a patient with HFrEF. Which code position reflects its distinguishing feature?", ["The fifth letter — multisite pacing for CRT", "The second letter — sensing", "The fourth letter — rate response", "The third letter — triggered mode"], 0, "The fifth letter describes multisite pacing when the device is for cardiac resynchronization therapy.")
    ]),

    // ------------------------------------------------------------------
    D("dev-icd-sudden-death", "Why an ICD prevents sudden cardiac death", "Sudden cardiac death is usually a fast ventricular rhythm — VT or VF — that a shock can reset, so an ICD that detects and shocks those rhythms saves the people most likely to have them: survivors of a prior arrest and hearts with a low ejection fraction.", [
      S("idea", "The idea", "<p>A pacemaker fixes a heart that is <strong>too slow</strong>. An <strong>ICD</strong> guards against a heart that suddenly goes <strong>dangerously fast and disorganized</strong> — ventricular tachycardia (VT) or ventricular fibrillation (VF). In those rhythms the ventricles cannot pump effectively, and without a shock the patient dies within minutes. That is sudden cardiac death.</p><p>An ICD is a smoke detector with a built-in sprinkler: it watches the rhythm continuously, and when it detects VT/VF it delivers a shock (or tries to overdrive pace it), then re-checks the rhythm.</p><p>Who gets one? Two groups: people who <strong>already had</strong> VT/VF arrest not caused by a fully reversible factor (<strong>secondary prophylaxis</strong>), and people whose hearts make it <strong>likely</strong> (<strong>primary prophylaxis</strong>) — most importantly a weak, scarred ventricle with a low ejection fraction.</p>" + clar("a ventricle damaged by MI or cardiomyopathy contains scar next to living muscle; that patchy tissue is the substrate for re-entrant VT that can degenerate into VF. That is why a low EF predicts sudden death and why the indications are EF-based.")),
      S("chain", "Cause → effect", chain([
        "Damaged myocardium (prior MI, cardiomyopathy) → low LVEF and scarred ventricle.",
        "Scarred ventricle → substrate for VT, which can degenerate into VF.",
        "VT/VF → ventricles cannot pump → no output → sudden cardiac death within minutes.",
        "ICD senses the fast ventricular rhythm → overdrive paces or delivers an 80-joule shock.",
        "After the shock it re-evaluates; if VT/VF persists it reverses polarity and shocks again, up to a programmed maximum.",
        "Normal rhythm restored → death prevented; the office is alerted and the patient goes to the ER to find and correct a reversible cause."
      ]) + Tbl(["Scenario", "Why ICD helps (or not)", "Fits"], [
        ["Survived VT/VF arrest, no completely reversible cause", "The substrate that caused it is still there", "<strong>Secondary prophylaxis</strong> — first line"],
        ["VF from a QT-prolonging drug that is stopped / VT from MI with stented artery", "Cause may be removed — debated", "Controversial"],
        ["LVEF ≤30% after MI (≥40 days post-MI)", "Scarred, weak ventricle → high VT/VF risk", "<strong>Primary prophylaxis</strong>"],
        ["LVEF ≤35% with NYHA II–III", "Same logic in symptomatic HF", "<strong>Primary prophylaxis</strong>"]
      ]) + HY("ICD = treats the too-fast lethal rhythm (VT/VF); pacemaker = treats the too-slow rhythm. Low EF → scar → VT/VF → sudden death.")),
      S("bedside", "Why it matters clinically", "<p>The objective asks you to contrast indications: pacemakers for <strong>symptomatic bradycardia/AV block</strong>; ICDs for <strong>survivors of VT/VF arrest</strong> (secondary) and for an <strong>EF of 30% or less</strong> (primary). Trials in arrest survivors showed ICDs beat multiple antiarrhythmics.</p><p>The secondary-prophylaxis caveat follows the same logic as pacemakers: if the arrest came from a <strong>completely reversible</strong> factor, the risk may have left with it — which is why the slides call cases like a stented MI or a stopped QT-prolonging drug controversial.</p><p>Modern transvenous ICDs can also pace a bradyarrhythmia, and if a patient needs both pacing and an ICD (or CRT), they are combined so everything runs off <strong>one pulse generator</strong>. A subcutaneous ICD (lead tunneled to the sternum) has limited pacing ability.</p>" + clar("the post-MI waiting period (at least 40 days) is given on the slides without a reason; the usual explanation is that EF measured soon after an MI can still improve as stunned muscle recovers, so the EF that qualifies a patient is the one measured after that window.")),
      S("traps", "Common traps", traps([
        "<strong>“An ICD is just a bigger pacemaker.”</strong> Its defining job is detecting and shocking VT/VF; pacing is secondary (and limited in a subcutaneous ICD).",
        "<strong>“Every arrest survivor gets an ICD.”</strong> Secondary prophylaxis applies when the arrest was <em>not</em> from a completely reversible factor; reversible cases are debated.",
        "<strong>“Low EF is a pacemaker indication.”</strong> Low EF predicts lethal <em>tachy</em>arrhythmia — an ICD indication (CRT is the pacing option for selected HFrEF).",
        "<strong>“Implant the ICD the day after the MI if EF is low.”</strong> The slides require at least 40 days post-MI for EF-based primary prophylaxis."
      ]))
    ], [
      Q("chain", "Why does a low LVEF after MI raise the risk of sudden cardiac death?", ["The scarred, weakened ventricle is a substrate for VT that can degenerate into VF", "Low EF causes complete heart block", "Low EF slows the sinus node until asystole", "Low EF raises the heart rate into sinus tachycardia"], 0, "Scar next to living myocardium supports ventricular tachyarrhythmias; VT/VF stops effective pumping, producing sudden death."),
      Q("idea", "What rhythm problem does an ICD primarily treat that a pacemaker does not?", ["Life-threatening ventricular tachyarrhythmias (VT/VF)", "Sinus bradycardia", "Complete heart block", "First-degree AV block"], 0, "An ICD detects VT/VF and shocks or overdrive paces; a pacemaker supports a rhythm that is too slow."),
      Q("chain", "An ICD delivers a shock for VF, re-evaluates, and VF persists. What does it do next?", ["Reverses polarity between the electrodes and delivers another shock, up to a programmed maximum", "Stops permanently after one shock", "Switches to asynchronous atrial pacing only", "Waits for external defibrillation before doing anything"], 0, "After a failed shock the ICD reverses polarity for subsequent shocks, then stops after the programmed maximum for that episode."),
      Q("bedside", "A patient survived a VF arrest with no completely reversible cause found. Which indication applies?", ["Secondary prophylaxis — ICD is first-line", "Primary prophylaxis — wait 40 days and recheck EF", "Pacemaker for bradycardia", "No device; antiarrhythmics are superior"], 0, "Survivors of VT/VF arrest not caused by a completely reversible factor have secondary-prophylaxis indications, and trials favored ICDs over multiple antiarrhythmics."),
      Q("bedside", "A patient had VF only while taking a QT-prolonging drug, which has been stopped. Why is an ICD controversial here?", ["The cause may have been completely reversible, so the ongoing risk may be gone", "ICDs cannot treat VF", "QT prolongation is a pacemaker indication", "Secondary prophylaxis requires an EF above 50%"], 0, "Secondary prophylaxis applies when the arrest was not caused by a completely reversible factor; removing the drug may remove the risk."),
      Q("chain", "EF falls from 50% to 28% in a patient 3 months after an MI. How does this change the device picture?", ["It creates a primary-prophylaxis ICD indication (LVEF ≤30%, at least 40 days post-MI)", "It creates a pacemaker indication", "It rules out an ICD because the MI was long ago", "It has no device implication"], 0, "A falling EF means more scarred, weak myocardium and higher VT/VF risk; LVEF ≤30% at least 40 days post-MI is a class I primary-prophylaxis indication."),
      Q("traps", "A patient needs both bradycardia pacing and an ICD. How should the devices be arranged?", ["Combined so everything runs off one pulse generator", "Two separate generators, one for each job", "Pacemaker only, since it can also defibrillate", "Subcutaneous ICD alone, since it paces fully"], 0, "The slides say a pacemaker should be combined with an ICD or CRT device if one is required; a subcutaneous ICD has limited pacing."),
      Q("traps", "Why should a qualifying EF be measured at least 40 days after an MI before primary-prophylaxis ICD?", ["EF soon after MI can still improve as stunned muscle recovers, so an early EF may overstate the risk", "ICD leads cannot be placed until the infarct calcifies", "Antiplatelet drugs must be stopped for 40 days", "VT never occurs in the first 40 days"], 0, "The slides require at least 40 days post-MI; the standard rationale is that early EF may recover, so the qualifying EF is measured after that window.")
    ]),

    // ------------------------------------------------------------------
    D("dev-emi-oversensing", "Electromagnetic interference and oversensing", "A device decides what to do based on the electrical signals it senses, so strong outside electrical noise can be mistaken for heart activity — a pacemaker then wrongly holds back and an ICD wrongly shocks.", [
      S("idea", "The idea", "<p>Both pacemakers and ICDs make decisions from what their leads <strong>sense</strong>. They can't tell the source of a signal — only that something electrical happened.</p><p><strong>Electrocautery</strong> during surgery (and, to a lesser degree, nerve stimulators and other electrical equipment) produces <strong>electromagnetic interference (EMI)</strong>. When the device picks this up and counts it as cardiac activity, that is <strong>oversensing</strong>.</p><p>What happens next depends on the device's job: a pacemaker that “hears beats” <strong>stops pacing</strong>; an ICD that “hears” a very fast rhythm <strong>shocks</strong>.</p>"),
      S("chain", "Cause → effect", chain([
        "Electrocautery or another strong electrical source produces EMI near the device.",
        "The lead picks up the EMI and the device interprets it as cardiac electrical activity (oversensing).",
        "Pacemaker: sees “normal beats” → inhibited → does not fire → in a pacemaker-dependent patient, profound bradycardia or asystole.",
        "ICD: sees a rapid “rhythm” → interprets it as VT/VF → inappropriate shock → patient movement on the table, hazard to patient and staff.",
        "Prevention: cardiology plans pre-op (especially surgery above the umbilicus); pacer is made asynchronous, ICD therapy is suspended, pads go on, and the device is restored and checked post-op."
      ]) + Tbl(["Device", "What oversensed EMI looks like to it", "Result", "Pre-op fix"], [
        ["Pacemaker", "The heart's own beats", "<strong>Inhibited</strong> → bradycardia/asystole if dependent", "Asynchronous pacing (magnet or reprogramming)"],
        ["ICD", "A fast ventricular rhythm", "<strong>Inappropriate shock</strong>", "Disable/suspend therapy; external pads on"]
      ]) + HY("Same mistake, opposite danger: EMI silences a pacemaker and triggers an ICD.")),
      S("bedside", "Why it matters clinically", "<p>This explains the perioperative rules: involve cardiology in pre-op planning (especially above the umbilicus, closer to the device), suspend ICD therapy, apply pacer/defib pads before prepping and draping, and after surgery reprogram or remove the magnet and monitor on telemetry in PACU/ICU — with closer interrogation if surgery was emergent or the device paced or shocked.</p><p>It also explains the everyday EMI counseling: keep cell phones, mobile devices, magnets, headphones, and wireless chargers about 6 inches (15 cm) from the device; stay at least 2 feet from welding equipment, high-voltage transformers, and motor-generators; limit hand-held metal detectors to under 30 seconds over the ICD site. Common household devices (microwaves, TVs, radios, computers, etc.) pose little or no risk.</p>" + clar("EMI strength falls off quickly with distance from the source, which is why the counseling is framed as keeping things a set distance away and why surgery closer to the generator (above the umbilicus) is the bigger concern.")),
      S("traps", "Common traps", traps([
        "<strong>“EMI makes a pacemaker fire too fast.”</strong> Oversensing makes a demand pacer think the heart is beating, so it <em>stops</em> firing.",
        "<strong>“EMI is only a pacemaker problem.”</strong> In an ICD it causes inappropriate shocks.",
        "<strong>“Only cautery matters.”</strong> Cautery is the biggest issue, but nerve stimulators and other electrical devices can also interfere.",
        "<strong>“Patients must avoid all electrical appliances.”</strong> Microwaves, TVs, radios, computers and similar household devices pose little or no risk."
      ]))
    ], [
      Q("chain", "During surgery, electrocautery is used near a pacemaker-dependent patient's demand pacer. Predict the rhythm.", ["Profound bradycardia or asystole, because the pacer is inhibited by the noise", "Rapid paced tachycardia", "No change, because cautery cannot be sensed", "Ventricular fibrillation from an ICD shock"], 0, "The pacer oversenses cautery as native beats, withholds pacing, and the dependent patient has no rhythm of their own."),
      Q("chain", "Electrocautery is used near an active ICD. What is the predicted danger?", ["The ICD oversenses noise as VT/VF and delivers an inappropriate shock", "The ICD stops sensing and permanently shuts off", "The ICD inhibits all pacing and causes asystole only", "The ICD drains its battery instantly"], 0, "EMI read as a fast ventricular rhythm triggers a shock, and patient movement from a shock is hazardous during surgery."),
      Q("idea", "What is oversensing?", ["The device interprets non-cardiac electrical signals (such as EMI) as cardiac activity", "The device fails to detect the heart's own beats", "The device paces more often than programmed due to rate response", "The device senses only the atrium"], 0, "The slides define oversensing as the device picking up EMI and interpreting it as cardiac electrical activity."),
      Q("bedside", "Which planned surgery most clearly calls for cardiology pre-op planning in a patient with an ICD?", ["A procedure above the umbilicus using electrocautery", "A dental cleaning with no electrical devices", "A procedure on the foot without cautery", "A blood draw"], 0, "Cautery is the main EMI source, and surgery above the umbilicus (closer to the device) especially warrants cardiology involvement."),
      Q("bedside", "A patient with an ICD asks where to keep his cell phone. What fits the reasoning about EMI?", ["Keep it at least about 6 inches (15 cm) away from the device site when on — such as not in a chest pocket over it", "Cell phones must never be used", "Keep it directly over the device so the device can sense it", "Distance does not matter for cell phones"], 0, "Cell phones, headphones, magnets, and wireless chargers should be kept about 6 inches from the device; interference is a near-field problem."),
      Q("traps", "Which household item is listed as posing little or no risk to a pacemaker or ICD?", ["Microwave oven", "Welding equipment", "High-voltage transformer", "A magnet held over the device"], 0, "Microwaves, TVs, radios, toasters, computers, and similar devices pose little or no risk; welding equipment and transformers require at least 2 feet of distance."),
      Q("chain", "Why must ICD therapy be suspended before surgery with cautery, rather than just pacing changed?", ["An inappropriate shock would cause patient movement that endangers the patient and surgical staff", "ICDs cannot pace during surgery", "Suspending therapy improves cautery performance", "The ICD battery would otherwise be damaged"], 0, "Oversensed cautery can trigger an ICD shock, and the resulting movement is a surgical hazard — so therapy is suspended and external pads are placed.")
    ]),

    // ------------------------------------------------------------------
    D("dev-magnet", "What a magnet does: pacemaker vs ICD", "A magnet over a pacemaker turns off its listening so it paces at a fixed rate, while a magnet over an ICD turns off its shocking — opposite effects that both protect the patient from oversensing during surgery.", [
      S("idea", "The idea", "<p>The magnet is the bedside way to change what a device does without reprogramming it — and its effect depends on the device's job.</p><p><strong>Pacemaker:</strong> most pacemakers respond to a magnet by switching to <strong>asynchronous pacing at a fixed rate</strong> (with a fixed AV delay). The device stops listening, so cautery noise can no longer inhibit it — it simply paces the heart for the whole procedure.</p><p><strong>ICD:</strong> a magnet <strong>suspends the ICD's function</strong> (its shock therapy), so noise can't trigger a shock. Because the ICD can no longer rescue the patient, external <strong>pacer/defib pads</strong> are applied before prepping and draping, and an external defibrillator/pacer is used if needed.</p><p>Remove the magnet (or reprogram) after surgery and the device returns to its normal behavior; the patient is monitored on telemetry.</p>"),
      S("chain", "Cause → effect", chain([
        "Surgery with cautery → risk of oversensing (pacemaker inhibited; ICD shocks inappropriately).",
        "Magnet over a pacemaker → asynchronous fixed-rate pacing → sensing is bypassed → EMI cannot inhibit pacing.",
        "Magnet over an ICD → ICD function suspended → EMI cannot trigger a shock → but the ICD will not treat real VT/VF either.",
        "So ICD patients have external pacer/defib pads placed before prep and drape → any real arrhythmia is treated externally.",
        "Magnet removed / device reprogrammed post-op → normal function returns → telemetry monitoring; interrogate if surgery was emergent or the device shocked/paced."
      ]) + Tbl(["", "Pacemaker + magnet", "ICD + magnet"], [
        ["Effect", "<strong>Asynchronous pacing</strong> at a fixed rate (fixed AV delay)", "<strong>Suspends</strong> ICD (shock) function"],
        ["Protects against", "Inhibition by cautery → asystole", "Inappropriate shock from cautery"],
        ["New risk created", "Fixed-rate impulses can compete with the heart; rate may be inadequate if the battery is near end of life", "No device rescue for real VT/VF"],
        ["Backup", "Monitoring", "<strong>External pacer/defib pads</strong> before prep/drape"]
      ]) + Mn("Magnet: pacer PACES, ICD PAUSES", "Pacemaker → paces asynchronously; ICD → shocks are paused.") + HY("Magnet over a pacemaker = asynchronous fixed-rate pacing; magnet over an ICD = shocks suspended, so external pads are mandatory.")),
      S("bedside", "Why it matters clinically", "<p>The objective asks you to recall the changes a magnet makes to each device during surgery. Linking it to sensing makes it predictable: the pacemaker change removes the <em>inhibition</em> problem; the ICD change removes the <em>inappropriate-shock</em> problem.</p><p>Two consequences follow directly from the slides: if the pacemaker is at the <strong>end of battery life</strong>, the magnet rate may not be adequate (aging pacemakers slow or change mode as the battery dwindles); and with the ICD paused, the team relies on <strong>external pads</strong> for any intraoperative emergency.</p>" + clar("magnet-mode asynchronous pacing has the same small risk as any asynchronous pacing — an impulse landing on the T wave's vulnerable period — which is why the patient is monitored closely while the magnet is on.")),
      S("traps", "Common traps", traps([
        "<strong>“A magnet turns a pacemaker off.”</strong> It switches it to fixed-rate asynchronous pacing — it keeps pacing.",
        "<strong>“A magnet makes an ICD pace asynchronously.”</strong> The lecture's ICD effect is suspension of ICD function (shocks), not asynchronous pacing.",
        "<strong>“With the magnet on, the ICD patient is protected from VT/VF.”</strong> The ICD is paused; protection comes from external pads.",
        "<strong>“Magnet rate is always adequate.”</strong> Near end of battery life, the rate may be too slow."
      ]))
    ], [
      Q("chain", "A magnet is placed over a pacemaker before surgery. What does the pacemaker do?", ["Paces asynchronously at a fixed rate with a fixed AV delay", "Stops pacing entirely", "Delivers a test shock", "Switches to sensing only"], 0, "For most pacemakers a magnet initiates asynchronous fixed-rate pacing, so the device paces throughout the procedure."),
      Q("chain", "A magnet is placed over an ICD before surgery. What changes?", ["ICD function (shock therapy) is suspended", "The ICD shocks at a fixed rate", "The ICD paces asynchronously at maximum rate", "Nothing; magnets affect only pacemakers"], 0, "The slides state ICD function is suspended during surgery by placing a magnet over the device."),
      Q("chain", "Why does putting a pacemaker in magnet mode prevent intraoperative asystole from cautery?", ["Asynchronous pacing does not depend on sensing, so cautery noise cannot inhibit it", "The magnet blocks cautery current from reaching the heart", "The magnet raises the battery voltage", "Magnet mode converts the pacer to an ICD"], 0, "Oversensing works by inhibiting a demand pacer; asynchronous pacing ignores what is sensed."),
      Q("bedside", "Why are pacer/defib pads applied before prepping and draping in an ICD patient whose device is under a magnet?", ["The ICD is suspended and cannot treat VT/VF, so any rescue must be external", "The pads boost the ICD's shock energy", "The pads prevent electrocautery from working", "Pads are needed only if the patient has a pacemaker"], 0, "Suspending the ICD prevents inappropriate shocks but also removes its rescue function; external pads provide the backup."),
      Q("bedside", "A pacemaker near the end of its battery life is placed in magnet mode. What problem might appear?", ["The magnet pacing rate may not be adequate", "The device will shock the patient", "The device will become inhibited by cautery", "Battery depletion has no effect in magnet mode"], 0, "The slides warn that at end of battery life the magnet rate may not be adequate, since aging pacemakers slow or change mode."),
      Q("traps", "Which statement contrasts the magnet effect correctly?", ["Pacemaker: keeps pacing at a fixed rate; ICD: shocks are paused", "Pacemaker: turned off; ICD: shocks at a fixed rate", "Both: turned completely off", "Pacemaker: shocks paused; ICD: paces asynchronously"], 0, "Magnet: pacer paces, ICD pauses."),
      Q("bedside", "The magnet is removed after surgery, but the device delivered shocks during the case. What follows?", ["Closer interrogation by cardiology, with telemetry monitoring", "No follow-up is needed because the magnet was removed", "Immediate generator change", "Lead extraction"], 0, "Post-op the device is restored and the patient monitored on telemetry; emergent surgery or device pacing/shocks during surgery call for closer interrogation.")
    ]),

    // ------------------------------------------------------------------
    D("dev-inappropriate-shocks", "Why ICDs shock when they shouldn't", "An ICD largely judges danger by how fast the ventricles are going, so a non-lethal atrial arrhythmia that drives the ventricular rate past the shock threshold can trigger a shock that wasn't needed.", [
      S("idea", "The idea", "<p>An ICD is programmed with a <strong>rate limit</strong>: ventricular rates above it are treated as possible VT/VF. That works well for real ventricular arrhythmias, but the ventricle can also go fast for <em>safer</em> reasons — most often an <strong>atrial arrhythmia</strong> (such as AF) conducting rapidly down to the ventricles.</p><p>If that ventricular rate crosses the limit, the ICD may shock even though the rhythm was not VT or VF. That is an <strong>inappropriate shock</strong>. Modern devices use discrimination algorithms to tell AF, sinus tachycardia, and other supraventricular tachycardias apart from VT/VF and minimize these shocks — but they still happen (one major trial: 11.5% of ICD patients received one, and 31.2% of all shocks were inappropriate).</p>"),
      S("chain", "Cause → effect", chain([
        "Atrial arrhythmia (e.g., AF) or another supraventricular tachycardia develops.",
        "Rapid conduction to the ventricles → ventricular rate climbs.",
        "Ventricular rate exceeds the programmed limit for shock delivery.",
        "If discrimination algorithms fail to classify it as supraventricular → ICD treats it as VT/VF → shock.",
        "Consequences: pain, ER visit (patients are told to go after any shock), admission to find reversible causes, and driving restriction (shock-free 6 months)."
      ]) + Tbl(["Fast rhythm", "Life-threatening?", "Should the ICD shock?"], [
        ["VT / VF", "Yes", "<strong>Yes</strong> — appropriate"],
        ["AF with rapid ventricular rate", "Not the target", "<strong>No</strong> — a shock here is inappropriate"],
        ["Sinus tachycardia", "No", "<strong>No</strong>"]
      ]) + HY("Inappropriate shock = an atrial (supraventricular) rhythm pushes the ventricular rate over the ICD's shock limit.")),
      S("bedside", "Why it matters clinically", "<p>Inappropriate shocks matter because every shock has real costs: <strong>ICD shocks hurt</strong>, the patient is counseled to go to the ER after any shock (and is generally admitted to correct reversible causes and see cardiology), the office is alerted, and most cardiologists recommend being <strong>shock-free for 6 months before driving</strong>.</p><p>The workup is the same either way: <strong>order a device interrogation</strong> — the ICD records events, so the stored rhythm shows whether the shock was for true VT/VF or for something like AF.</p>"),
      S("traps", "Common traps", traps([
        "<strong>“Any shock means the patient had VT/VF.”</strong> Nearly a third of shocks in a major trial were inappropriate; interrogate to see the rhythm.",
        "<strong>“Inappropriate shocks are caused only by EMI.”</strong> EMI can cause them during surgery, but the lecture's typical cause is an atrial arrhythmia raising the ventricular rate.",
        "<strong>“A shock that was inappropriate needs no ER visit.”</strong> The patient can't know at home; they are counseled to go to the ER after any shock.",
        "<strong>“Modern ICDs can't misclassify.”</strong> Discrimination algorithms minimize, not eliminate, shocks for AF, sinus tachycardia and other SVTs."
      ]))
    ], [
      Q("chain", "An ICD patient develops AF with a rapid ventricular response that exceeds the device's rate limit. What can happen?", ["An inappropriate shock, because the ICD may treat the fast ventricular rate as VT/VF", "Nothing, because ICDs ignore atrial rhythms completely", "The ICD switches to asynchronous pacing", "The ICD suspends itself"], 0, "Typically, inappropriate shocks occur when an atrial arrhythmia accelerates the ventricular rate beyond the shock limit."),
      Q("idea", "What makes an ICD shock “inappropriate”?", ["It was not triggered by accurate detection of VT or VF", "It was delivered at less than 80 joules", "It occurred during sleep", "It successfully converted VF"], 0, "An inappropriate shock is one not precipitated by accurate detection of a malignant ventricular arrhythmia."),
      Q("chain", "Which change would most reduce inappropriate shocks?", ["Better discrimination of AF, sinus tachycardia, and other SVTs from VT/VF", "Lowering the rate limit for shock delivery", "Raising the shock energy", "Removing the device's ability to record events"], 0, "Discrimination algorithms are designed to minimize shocks for non-life-threatening supraventricular tachyarrhythmias; a lower rate limit would catch more SVT."),
      Q("bedside", "A patient's ICD fires once at home and he now feels fine. What is the appropriate next step?", ["Go to the ER; interrogate the device and look for reversible causes", "Stay home since he feels fine", "Remove the device", "Place a magnet over it permanently"], 0, "Patients are told to go to the ER if the ICD fires; they are generally admitted, reversible causes corrected, and the device interrogated."),
      Q("bedside", "How do you tell whether an ICD shock was appropriate?", ["Interrogate the device to review the recorded rhythm", "Check a troponin", "Apply a magnet and watch the ECG", "Order a chest x-ray"], 0, "Modern ICDs record cardiac events; interrogation shows whether the shocked rhythm was VT/VF or a supraventricular rhythm."),
      Q("traps", "An ICD patient received a shock for AF. Why does this still disrupt his life even though the rhythm wasn't lethal?", ["Shocks hurt, prompt an ER visit, and most cardiologists advise 6 shock-free months before driving", "AF shocks permanently damage the leads", "Any shock requires immediate device explant", "Inappropriate shocks drain the battery to zero"], 0, "The slides list pain, the ER/admission instruction, and the 6-month shock-free driving recommendation as reasons inappropriate shocks matter.")
    ]),

    // ------------------------------------------------------------------
    D("dev-infection-explant", "Why device infection means removing everything", "Bacteria that seed the leads or pocket live on hardware that antibiotics cannot sterilize, so any infected pacemaker or ICD — generator and leads — must come out, and a new device waits until a course of antibiotics is done.", [
      S("idea", "The idea", "<p>A pacemaker or ICD is a foreign body: a generator in a skin pocket connected to leads that sit inside the veins and the right heart. Once bacteria reach it, they settle on the hardware — the slides describe bacteremia seeding a <strong>small clot on the leads</strong> — and the infection keeps <strong>re-seeding the blood</strong>, producing a <strong>persistent bacteremia</strong>.</p><p>Because the generator, pocket, and leads are all connected, treating only part of the system leaves infected hardware behind. That is why the rule is absolute: <strong>anytime a device becomes infected, the device and the leads are explanted</strong>, antibiotics are given for a period, and only then is a new device implanted.</p>" + clar("antibiotics in the blood reach bacteria on a non-living surface poorly, so infected hardware usually cannot be sterilized in place — the reason removal, not antibiotics alone, is required.")),
      S("chain", "Cause → effect", chain([
        "Route in: pocket infected at insertion, pocket erosion (e.g., from weight loss), or bacteremia seeding the leads.",
        "Bacteria settle on hardware (a small clot/vegetation on the lead).",
        "Hardware keeps shedding bacteria into the blood → persistent bacteremia; a lead vegetation may be seen on TEE.",
        "Antibiotics alone cannot clear bacteria living on the device.",
        "Explant the generator and all leads → source removed → antibiotic course → new device implanted afterward."
      ]) + Tbl(["Factor", "Effect on infection risk", "Why (reasoning)"], [
        ["Generator change vs new implant", "<strong>Higher</strong> with generator change", "Reopening an existing pocket around hardware"],
        ["Pocket hematoma", "<strong>↑ from 0.98% to 22.7%</strong>", "Clot in the pocket is a place for bacteria to grow"],
        ["Weight loss", "Pocket erosion → exposed device", "Less tissue covering the generator"]
      ]) + HY("Infected device = remove generator AND leads, treat with antibiotics, then re-implant.")),
      S("bedside", "Why it matters clinically", "<p>Infection presents two ways the slides describe: a <strong>pocket</strong> problem (infected incision, eroding pocket) or a <strong>lead</strong> problem from bacteremia — persistent bacteremia with a vegetation that may be seen on <strong>TEE</strong>. The second ties to the endocarditis lecture: hardware in the right heart is a nidus just like a damaged valve.</p><p>Prevention follows from the risk factors: hold anticoagulants and antiplatelets before implant as instructed (a pocket hematoma raises infection risk more than twentyfold), and the 1–2 week wound check after implant is the first look at the pocket.</p>" + clar("linking the instruction to hold anticoagulant/antiplatelet drugs pre-procedure to hematoma prevention is standard reasoning; the slides list both facts separately.")),
      S("traps", "Common traps", traps([
        "<strong>“Treat a lead infection with IV antibiotics and leave the device.”</strong> The rule is explant of the device and leads whenever it is infected.",
        "<strong>“Just swap the generator.”</strong> A generator change leaves the leads; if the system is infected, infected leads remain. (Generator changes themselves carry higher infection risk than a new implant.)",
        "<strong>“Re-implant right away on the other side.”</strong> A period of antibiotic therapy comes before a new device.",
        "<strong>“A pocket hematoma is just cosmetic.”</strong> It raises infection risk from 0.98% to 22.7%."
      ]))
    ], [
      Q("chain", "A patient with an ICD has persistent bacteremia and a vegetation on a lead on TEE. Why will antibiotics alone fail?", ["Bacteria on the hardware keep re-seeding the blood, and antibiotics cannot sterilize the device in place", "Antibiotics cannot enter the bloodstream", "The bacteremia is caused by the battery", "Vegetations on leads are sterile"], 0, "The lead is a persistent source; removing the device and leads removes the source, and then antibiotics can clear the infection."),
      Q("idea", "What is the management whenever a pacemaker or ICD becomes infected?", ["Explant the device and leads, give antibiotics, then implant a new device", "Antibiotics only, keeping the device", "Generator change only", "Remove the leads but keep the generator"], 0, "Anytime a pacemaker or ICD becomes infected, the device and the leads must be explanted, followed by antibiotics before a new device."),
      Q("chain", "A pocket hematoma forms after implant. Predict the effect on infection risk.", ["It rises sharply — from about 1% to about 23%", "It falls, because blood carries white cells", "No change", "It rises only if the patient is on antibiotics"], 0, "The slides report hematoma raises infection risk from 0.98% to 22.7%."),
      Q("chain", "Which procedure is more likely to lead to device infection?", ["A generator change", "A first-time (de novo) implant", "They carry identical risk", "Neither can cause infection"], 0, "The slides state a generator change is more likely to cause a device infection than a de novo implant."),
      Q("bedside", "A thin, elderly patient loses a lot of weight and the skin over her pacemaker thins and breaks down. What process is this?", ["Pocket erosion — a route to device infection", "Lead fracture", "Normal battery depletion", "Oversensing"], 0, "Pocket erosion from weight loss is one of the listed ways a device becomes infected."),
      Q("traps", "A device infection is treated by replacing only the generator. What is the problem?", ["The infected leads remain, so the source of infection stays", "The new generator will be incompatible with antibiotics", "Nothing — a generator change is the treatment", "The patient will lose pacing permanently"], 0, "A generator change replaces only the pocket device and leaves the wires; with an infected system, both device and leads must be removed."),
      Q("bedside", "Why is a patient told to hold anticoagulant and antiplatelet drugs before pacemaker placement?", ["To reduce bleeding into the pocket, since a hematoma sharply increases infection risk", "Because these drugs interfere with sensing", "Because they shorten battery life", "Because they cause lead fracture"], 0, "Holding AC and antiplatelets reduces bleeding; a pocket hematoma raises infection risk from 0.98% to 22.7%.")
    ])
  ]);
}());
